package com.sakalti.modifier;
import net.minecraft.entity.effect.*; import net.minecraft.entity.LivingEntity; import net.minecraft.world.World; import net.minecraft.item.ItemStack; import slimeknights.tconstruct.library.modifiers.Modifier; import slimeknights.tconstruct.library.tools.context.ToolAttackContext; import slimeknights.tconstruct.library.tools.nbt.IToolStackView;
public class AuroVisionModifier extends Modifier { @Override public int afterEntityHit(IToolStackView tool,int level,ToolAttackContext ctx,float damage){LivingEntity a=ctx.getAttacker();if(a!=null&&!a.getWorld().isClient){a.addStatusEffect(new StatusEffectInstance(StatusEffects.GLOWING,20,4));a.addStatusEffect(new StatusEffectInstance(StatusEffects.RESISTANCE,20,4));}return 0;} @Override public void onInventoryTick(IToolStackView tool,int level,World world,LivingEntity e,int slot,boolean selected,boolean correct,ItemStack stack){if(!world.isClient&&!tool.isBroken()&&correct)e.addStatusEffect(new StatusEffectInstance(StatusEffects.NIGHT_VISION,220,0,false,true));}}
